'use strict';
const DAY_THEMES={quick:{title:'Nhanh gọn đầu tuần',description:'Ưu tiên món ít thao tác, khoảng 20–30 phút; chọn rau và canh đơn giản.',protein:null,max:30},fish:{title:'Đổi vị với món cá',description:'Gợi ý món cá nếu phù hợp sở thích; thêm rau và canh, đổi nhóm đạm giữa các bữa.',protein:'fish',max:35},plant:{title:'Đậu hũ / trứng đổi vị',description:'Luân phiên với đậu hũ hoặc trứng, tránh để các bữa giống nhau. Vẫn kiểm tra thành phần và nguyên liệu cần tránh.',protein:'plant',max:30},favorites:{title:'Một món nhà mình thích',description:'Ưu tiên món đã đánh dấu yêu thích, thêm món rau/canh theo số món gia đình chọn.',protein:null,max:40},pantry:{title:'Tận dụng đồ đang có',description:'Kiểm tra thực phẩm còn trong tủ và hạn đã nhập trước khi mua thêm; không tự coi thực phẩm quá hạn là dùng được.',protein:null,max:30},soup:{title:'Cuối tuần ăn món nước',description:'Phở, bún, mì, hủ tiếu, cháo hoặc súp. Các món nhanh ghi rõ điều kiện có sẵn nước dùng / cơm chín.',protein:null,max:35},batch:{title:'Nấu thong thả, chuẩn bị tuần mới',description:'Chọn món nhiều thời gian hơn nếu muốn; chia nguyên liệu và chuẩn bị kế hoạch, không tự suy đoán hạn bảo quản.',protein:null,max:60}};
const DEFAULT_DAY_THEMES={1:'quick',2:'fish',3:'plant',4:'favorites',5:'pantry',6:'soup',0:'batch'};
function dayTheme(date,state){const weekday=parseDate(date).getDay(),id=state.preferences.dayThemes?.[weekday]||DEFAULT_DAY_THEMES[weekday];return{id,...DAY_THEMES[id]||DAY_THEMES.quick}}
function plannerRecipeBonus(date,r,state){const theme=dayTheme(date,state);let score=r.time<=theme.max?2:0;if(theme.protein&&r.protein===theme.protein)score+=5;if(theme.id==='plant'&&r.protein==='egg')score+=4;if(theme.id==='favorites'&&r.favorite)score+=5;if(theme.id==='pantry')score+=r.ingredients.filter(i=>stock(state,i.id)>0).length*2;return score}
function getShop(state,id){return(state.stores||[]).find(s=>s.id===id)||null}
function shoppingStore(state,week,start,end,id){const record=week.shopLocations?.[purchaseScope(start,end)]?.[id];const storeId=record?.storeId??state.preferredStores?.[id]??'';return{storeId,store:getShop(state,storeId),note:record?.note||''}}
function setShoppingStore(state,week,start,end,id,storeId,note='',remember=true){if(!Object.hasOwn(INGREDIENTS,id))throw Error('Nguyên liệu không tồn tại.');if(storeId&&!getShop(state,storeId))throw Error('Cửa hàng không tồn tại.');week.shopLocations??={};week.shopLocations[purchaseScope(start,end)]??={};week.shopLocations[purchaseScope(start,end)][id]={storeId,note:String(note).slice(0,200)};if(remember){state.preferredStores??={};state.preferredStores[id]=storeId}}
function mapURL(store){return store?.address?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(store.name+' '+store.address):null}
function validPlanningState(s){if(s.preferences?.dayThemes&&(!s.preferences.dayThemes||!Object.entries(s.preferences.dayThemes).every(([d,t])=>/^[0-6]$/.test(d)&&Object.hasOwn(DAY_THEMES,t))))return false;if(s.stores!==undefined&&(!Array.isArray(s.stores)||s.stores.length>100||!s.stores.every(x=>typeof x.id==='string'&&typeof x.name==='string'&&x.name.length>0&&x.name.length<=100&&typeof x.address==='string'&&x.address.length<=300)))return false;if(s.preferredStores!==undefined&&(!s.preferredStores||typeof s.preferredStores!=='object'||Array.isArray(s.preferredStores)||!Object.entries(s.preferredStores).every(([id,v])=>Object.hasOwn(INGREDIENTS,id)&&typeof v==='string')))return false;for(const w of Object.values(s.weeks||{})){if(w.shopLocations!==undefined&&(!w.shopLocations||typeof w.shopLocations!=='object'||Array.isArray(w.shopLocations)||!Object.values(w.shopLocations).every(rows=>rows&&typeof rows==='object'&&!Array.isArray(rows)&&Object.entries(rows).every(([id,x])=>Object.hasOwn(INGREDIENTS,id)&&x&&typeof x.storeId==='string'&&typeof x.note==='string'&&x.note.length<=200))))return false}if(s.errands!==undefined&&(!Array.isArray(s.errands)||!s.errands.every(r=>r&&typeof r.id==='string'&&typeof r.item==='string'&&r.item.length>0&&r.item.length<=150&&typeof r.qty==='string'&&r.qty.length<=80&&typeof r.storeId==='string'&&typeof r.note==='string'&&r.note.length<=500&&typeof r.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Array.isArray(r.targets)&&r.targets.every(x=>typeof x==='string')&&typeof r.done==='boolean')))return false;return true}
